/// <summary>
/// AVA/WEN 2024/09/06    AVA_012455_TaxMarkupLedgerAccounts
/// </summary>
/// <returns>LedgerDimensionDefaultAccount</returns>
LedgerDimensionDefaultAccount operationAccountMarkup()
{
    KCS_TaxMarkup   taxMarkupSpec;

    LedgerDimensionDefaultAccount locledgerAccount = next operationAccountMarkup();

    switch (markupTrans.markupTable().CustType)
    {
        case MarkupType::LedgerAccount :
            taxMarkupSpec = KCS_TaxMarkup::find(markupTrans.MarkupCode, markupTrans.TaxGroup, CustVendACType::Cust);
            if(taxMarkupSpec)
            {
                locledgerAccount = taxMarkupSpec.LedgerDimension;
            }
            break;
    }

    return locledgerAccount;
}
